7	export interface GuardResult {
8	  model: string;
9	  results: Array<{
10	    categories: Record<string, boolean>;
11	    category_scores: Record<string, number>;
12	    flagged: boolean;
13	    payload?: {
14	      pii?: Array<{
15	        entity_type: string;
16	        start: number;
17	        end: number;
18	        pii: string;
19	      }>;
20	    };
21	  }>;
22	}
