24	export interface AdaptiveRequest {
25	  prompt: string;
26	  policies?: string[];
27	}
28	
29	export interface AdaptiveResult {
30	  model: string;
31	  adaptedPrompt: string;
32	  modifications: Array<{
33	    type: string;
34	    reason: string;
35	    original: string;
36	    modified: string;
37	  }>;
38	}
