40	async function makeRequest(endpoint: string, input: string): Promise<GuardResult> {
41	  try {
42	    const response = await fetchWithCache(
43	      `${API_BASE_URL}${endpoint}`,
44	      {
45	        method: 'POST',
46	        headers: {
47	          'Content-Type': 'application/json',
48	        },
49	        body: JSON.stringify({ input }),
50	      },
51	      undefined,
52	      'json',
53	    );
54	
55	    if (!response.data) {
56	      throw new Error('No data returned from API');
57	    }
58	
59	    return response.data as GuardResult;
60	  } catch (error) {
61	    logger.error(`Guardrails API error: ${error}`);
62	    throw error;
63	  }
64	}
65	
66	async function makeAdaptiveRequest(request: AdaptiveRequest): Promise<AdaptiveResult> {
67	  try {
68	    const response = await fetchWithCache(
69	      `${API_BASE_URL}/adaptive`,
70	      {
71	        method: 'POST',
72	        headers: {
73	          'Content-Type': 'application/json',
74	        },
75	        body: JSON.stringify({
76	          prompt: request.prompt,
77	          policies: request.policies || [],
78	        }),
79	      },
80	      undefined,
81	      'json',
82	    );
83	
84	    if (!response.data) {
85	      throw new Error('No data returned from API');
86	    }
87	
88	    return response.data as AdaptiveResult;
89	  } catch (error) {
90	    logger.error(`Guardrails API error: ${error}`);
91	    throw error;
92	  }
93	}
