95	const guardrails = {
96	  async guard(input: string): Promise<GuardResult> {
97	    return makeRequest('/guard', input);
98	  },
99	
100	  async pii(input: string): Promise<GuardResult> {
101	    return makeRequest('/pii', input);
102	  },
103	
104	  async harm(input: string): Promise<GuardResult> {
105	    return makeRequest('/harm', input);
106	  },
107	
108	  async adaptive(request: AdaptiveRequest): Promise<AdaptiveResult> {
109	    return makeAdaptiveRequest(request);
110	  },
111	};
112	
113	export default guardrails;
