51	export function getUserAuthInfo(): UserAuthInfo {
52	  const globalConfig = readGlobalConfig();
53	  const email = globalConfig?.account?.email || null;
54	  const isLoggedIntoCloud = !!(globalConfig?.cloud?.apiKey || process.env.PROMPTFOO_API_KEY);
