64	  let globalConfig = readGlobalConfig();
65	  if (!globalConfig?.id) {
66	    const newId = crypto.randomUUID();
67	    globalConfig = { ...globalConfig, id: newId };
68	    writeGlobalConfig(globalConfig);
69	    return newId;
70	  }
71	
72	  return globalConfig.id;
